"""Generates the evaluation table from the test run itself (PDF §5: "generated by the test run").

Scenario tests carry `@pytest.mark.scenario(id, title, expected=..., covers=...)` and record what
they actually observed with the `observe` fixture (values read from the database, the backend,
the outbox or the model log, not restated expectations). After the session, every scenario that
ran is written to artifacts/eval/ as Markdown and JSON with the columns
scenario · expected · actual · pass/fail · notes. A failing scenario's "actual" is the failure
itself. Nothing here is hand-written per run.
"""

from __future__ import annotations

import json
import os
import subprocess
from collections.abc import Callable, Generator
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

import pytest

OUT_DIR = Path(__file__).resolve().parents[1] / "artifacts" / "eval"
_OBSERVED = pytest.StashKey[list[str]]()
_RESULTS: dict[str, dict[str, Any]] = {}
_SCENARIOS: dict[str, pytest.Item] = {}


def pytest_configure(config: pytest.Config) -> None:
    config.addinivalue_line(
        "markers", "scenario(id, title, expected, covers): simulated-user scenario reported in the eval table"
    )


@pytest.fixture
def observe(request: pytest.FixtureRequest) -> Callable[[str], None]:
    """Record an observed fact for the eval table's 'actual' column."""
    observed: list[str] = request.node.stash.setdefault(_OBSERVED, [])
    record: Callable[[str], None] = observed.append
    return record


def pytest_collection_modifyitems(items: list[pytest.Item]) -> None:
    for item in items:
        if item.get_closest_marker("scenario") is not None:
            _SCENARIOS[item.nodeid] = item


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item: pytest.Item, call: pytest.CallInfo[None]) -> Generator[None, Any, None]:
    outcome = yield
    report = outcome.get_result()
    if item.nodeid not in _SCENARIOS:
        return
    if report.when == "call" or (report.when == "setup" and report.failed):
        observed: list[str] = [*item.stash.get(_OBSERVED, []), *_end_state(item)]
        detail = ""
        if report.failed:
            detail = str(getattr(call.excinfo, "value", "") or report.longreprtext.splitlines()[-1:])
        _RESULTS[item.nodeid] = {
            "passed": report.passed,
            "failure": detail.splitlines()[0][:300] if detail else "",
            "seconds": round(report.duration, 2),
            "observed": list(observed),
        }


def pytest_sessionfinish(session: pytest.Session) -> None:
    if not _RESULTS:
        return
    rows = []
    for nodeid, item in _SCENARIOS.items():
        if nodeid not in _RESULTS:
            continue
        marker = item.get_closest_marker("scenario")
        assert marker is not None
        sid, title = marker.args[0], marker.args[1]
        res = _RESULTS[nodeid]
        actual = "; ".join(res["observed"]) if res["observed"] else "(no observations recorded)"
        if not res["passed"]:
            actual = f"FAILED: {res['failure']}" + (f" (observed so far: {actual})" if res["observed"] else "")
        rows.append(
            {
                "id": sid,
                "scenario": title,
                "expected": marker.kwargs.get("expected", ""),
                "actual": actual,
                "result": "pass" if res["passed"] else "FAIL",
                "notes": f"{marker.kwargs.get('covers', '')}; test `{nodeid.split('::')[-1]}`; {res['seconds']} s",
            }
        )
    rows.sort(key=lambda r: r["id"])
    total, passed = len(rows), sum(r["result"] == "pass" for r in rows)
    meta = {
        "generated_at": datetime.now(UTC).isoformat(timespec="seconds"),
        "commit": _commit(),
        "scenarios_run": total,
        "scenarios_marked": len(_SCENARIOS),
        "passed": passed,
        "complete_run": total == len(_SCENARIOS),
    }
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    (OUT_DIR / "eval_results.json").write_text(
        json.dumps({"meta": meta, "rows": rows}, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )
    lines = [
        "# Evaluation table",
        "",
        f"Generated by the test run at {meta['generated_at']} (commit {meta['commit']}): "
        f"{passed}/{total} scenarios passed"
        + ("" if meta["complete_run"] else f" — PARTIAL RUN: {total} of {len(_SCENARIOS)} marked scenarios ran")
        + ". Offline: scripted model, seeded mocks, fake clock, real PostgreSQL. Do not edit by hand.",
        "",
        "| Scenario | Expected | Actual | Pass/fail | Notes |",
        "| --- | --- | --- | --- | --- |",
    ]
    for r in rows:
        cells = [f"**{r['id']}** {r['scenario']}", r["expected"], r["actual"], r["result"], r["notes"]]
        lines.append("| " + " | ".join(c.replace("|", "\\|").replace("\n", " ") for c in cells) + " |")
    (OUT_DIR / "eval_table.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


def _commit() -> str:
    """The commit under test (passed in by scripts/dev.sh; the container has no git)."""
    passed_in = os.environ.get("ERRAND_GIT_COMMIT", "").strip()
    if passed_in:
        return passed_in
    try:
        out = subprocess.run(
            ["git", "rev-parse", "--short", "HEAD"],  # noqa: S607 - developer tool on PATH, fixed arguments
            capture_output=True,
            text=True,
            check=False,
            cwd=OUT_DIR.parents[1],
            timeout=5,
        )
    except (OSError, subprocess.TimeoutExpired):
        return "unknown"
    return out.stdout.strip() or "unknown"


def _end_state(item: pytest.Item) -> list[str]:
    """Observed end state, read from the test's database after the scenario ran."""
    db = getattr(item, "funcargs", {}).get("db")
    if db is None:
        return []
    with db.txn() as conn:

        def counts(query: str) -> str:
            rows = conn.execute(query).fetchall()
            return ", ".join(f"{r['k']}×{r['n']}" for r in rows) or "none"

        states = counts("SELECT state AS k, count(*) AS n FROM sessions GROUP BY state ORDER BY 1")
        ops = counts("SELECT action || ':' || status AS k, count(*) AS n FROM operations GROUP BY 1 ORDER BY 1")
        tools = counts(
            "SELECT payload->>'tool' AS k, count(*) AS n FROM trace_events WHERE kind = 'tool.call' "
            "GROUP BY 1 ORDER BY 1"
        )
        model = conn.execute(
            "SELECT count(*) AS n, count(*) FILTER (WHERE payload->>'accepted' IS NULL) AS rejected"
            " FROM trace_events WHERE kind = 'model.call'"
        ).fetchone()
        booked = conn.execute("SELECT count(*) AS n FROM mock_bookings WHERE hold_id IS NOT NULL").fetchone()
        notes = conn.execute("SELECT count(*) AS n FROM outbox").fetchone()
    out = [
        f"end state: sessions {states}",
        f"new bookings={booked['n'] if booked else 0}",
        f"operations {ops}",
        f"tool calls {tools}",
        f"model calls={model['n'] if model else 0} (rejected {model['rejected'] if model else 0})",
    ]
    if notes and notes["n"]:
        out.append(f"notifications={notes['n']}")
    return out
